local CiboriumMaker = {}
local PRODUCTS = {
    pewter_ciborium = { name = "Pustrast ciborij", tinCost = 2, time = 2, cost = 30, sanctity = 4, description = "Pustrast ciborij za hostije." },
    brass_ciborium = { name = "Medeninast ciborij", brassCost = 2, time = 3, cost = 75, sanctity = 7, prestige = 1, description = "Medeninast ciborij z vinjeto." },
    silver_ciborium = { name = "Srebrni ciborij", silverCost = 2, time = 5, cost = 200, sanctity = 11, prestige = 4, happiness = 1, description = "Srebrni ciborij za župnije." },
    gold_ciborium = { name = "Zlati ciborij", goldCost = 1, silverCost = 1, time = 7, cost = 460, sanctity = 15, prestige = 10, happiness = 2, description = "Zlati ciborij za slovesne maše." },
    jewel_ciborium = { name = "Draguljni ciborij", goldCost = 2, silverCost = 1, jewelCost = 1, time = 10, cost = 950, sanctity = 20, prestige = 20, happiness = 4, description = "Ciborij z dragulji za katedralo." },
    royal_tabernacle_ciborium = { name = "Kraljevski tabernakelj ciborij", goldCost = 3, silverCost = 2, jewelCost = 3, pearlCost = 1, time = 15, cost = 2400, sanctity = 32, prestige = 60, happiness = 12, description = "Veliki kraljevski ciborij z dragulji in biseri za tabernakelj." },
}
local BUILDINGS = {
    workshop = { name = "Ciborijska delavnica", cost = { gold = 280, wood = 120 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Ciborijska kovačija", cost = { gold = 850, wood = 220, stone = 200, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 1800, wood = 300, stone = 400, silver = 25, jewel = 6 }, upkeep = 42, qualityBonus = 30 },
    royal_ciborium_atelier = { name = "Kraljevski atelje ciborijev", cost = { gold = 7000, wood = 600, stone = 800, gold = 50, jewel = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 33 },
}
CiboriumMaker.tinStock = 12; CiboriumMaker.brassStock = 8; CiboriumMaker.silverStock = 8; CiboriumMaker.goldStock = 6; CiboriumMaker.jewelStock = 6; CiboriumMaker.pearlStock = 4
CiboriumMaker.productStock = {}; CiboriumMaker.buildings = {}; CiboriumMaker.maker = nil; CiboriumMaker.activeMaking = {}; CiboriumMaker.totalProducts = 0; CiboriumMaker.dayTimer = 0
function CiboriumMaker.init() CiboriumMaker.tinStock=12; CiboriumMaker.brassStock=8; CiboriumMaker.silverStock=8; CiboriumMaker.goldStock=6; CiboriumMaker.jewelStock=6; CiboriumMaker.pearlStock=4; CiboriumMaker.productStock={}; CiboriumMaker.buildings={}; CiboriumMaker.maker=nil; CiboriumMaker.activeMaking={}; CiboriumMaker.totalProducts=0; CiboriumMaker.dayTimer=0; print("[CiboriumMaker] Royal Ciborium Maker System initialized (6 products, 4 buildings)") end
function CiboriumMaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CiboriumMaker.maker={name=n or ("Ciborijar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ciborijar najet: %s (spretnost: %d)",CiboriumMaker.maker.name,s),"success") end; return true end
function CiboriumMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CiboriumMaker.build(id) local ok,e=CiboriumMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CiboriumMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CiboriumMaker.getQualityBonus() local b=0; for _,bd in ipairs(CiboriumMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CiboriumMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.tinCost and CiboriumMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.brassCost and CiboriumMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and CiboriumMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CiboriumMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CiboriumMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CiboriumMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CiboriumMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CiboriumMaker.maker then return false,"Potreben ciborijar" end; return true end
function CiboriumMaker.make(pt,qty) qty=qty or 1; local ok,e=CiboriumMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.tinCost then CiboriumMaker.tinStock=CiboriumMaker.tinStock-d.tinCost*qty end; if d.brassCost then CiboriumMaker.brassStock=CiboriumMaker.brassStock-d.brassCost*qty end; if d.silverCost then CiboriumMaker.silverStock=CiboriumMaker.silverStock-d.silverCost*qty end; if d.goldCost then CiboriumMaker.goldStock=CiboriumMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CiboriumMaker.jewelStock=CiboriumMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CiboriumMaker.pearlStock=CiboriumMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CiboriumMaker.maker then t=math.max(1,t-math.floor(CiboriumMaker.maker.skill/12)) end; table.insert(CiboriumMaker.activeMaking,{id="ciborium_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sanctity=d.sanctity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CiboriumMaker.completeMaking(m) local q=1.0+(CiboriumMaker.getQualityBonus()/100); if CiboriumMaker.maker then q=q+(CiboriumMaker.maker.skill/180) end; q=math.min(2.0,q); CiboriumMaker.productStock[m.productType]=(CiboriumMaker.productStock[m.productType] or 0)+m.quantity; CiboriumMaker.totalProducts=CiboriumMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CiboriumMaker.maker then CiboriumMaker.maker.itemsMade=CiboriumMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CiboriumMaker.maker.skill=math.min(100,CiboriumMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ciborij izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ciborium.completed",{productName=m.productName,sanctity=m.sanctity}) end end
function CiboriumMaker.update(dt) if not _G.state then return end; CiboriumMaker.dayTimer=CiboriumMaker.dayTimer+dt; if CiboriumMaker.dayTimer>=30 then CiboriumMaker.dayTimer=0; for i=#CiboriumMaker.activeMaking,1,-1 do local m=CiboriumMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CiboriumMaker.completeMaking(m); table.remove(CiboriumMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CiboriumMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CiboriumMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CiboriumMaker.getStats() return {tinStock=CiboriumMaker.tinStock,brassStock=CiboriumMaker.brassStock,silverStock=CiboriumMaker.silverStock,goldStock=CiboriumMaker.goldStock,jewelStock=CiboriumMaker.jewelStock,pearlStock=CiboriumMaker.pearlStock,productStock=CiboriumMaker.productStock,numBuildings=#CiboriumMaker.buildings,hasMaker=CiboriumMaker.maker~=nil,makerName=CiboriumMaker.maker and CiboriumMaker.maker.name or "—",makerSkill=CiboriumMaker.maker and CiboriumMaker.maker.skill or 0,activeMaking=#CiboriumMaker.activeMaking,totalProducts=CiboriumMaker.totalProducts} end
return CiboriumMaker
